questions.q:
O que a política abaixo permite?
CREATE POLICY "Ver tarefa propria ou compartilhada"
ON tarefas FOR SELECT
USING (
  auth.uid() = usuario_id
  OR id IN (
    SELECT tarefa_id FROM compartilhamentos
    WHERE usuario_convidado_id = auth.uid()
  )
);
